import{_ as o,o as r,c as s,a2 as t}from"./chunks/framework.CqGPl1zp.js";const i="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/01.png",c="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/02.png",p="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/03.png",n="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/04.png",d="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/05.png",l="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/06.png",m="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/08.png",u="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/09.png",h="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/10.png",g="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/11.png",a="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/21.png",_="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/22.png",E="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/23.png",A="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/24.png",b="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/32.png",y="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/34.png",f="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/35.png",k="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/36.png",D="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/33.png",S="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/41.png",B="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/42.png",F="/newx-doc/img/%E7%9F%AD%E4%BF%A1%E9%85%8D%E7%BD%AE/45.png",V=JSON.parse('{"title":"短信配置","description":"","frontmatter":{},"headers":[],"relativePath":"sms.md","filePath":"sms.md","lastUpdated":null}'),v={name:"sms.md"};function x(q,e,P,I,C,w){return r(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="短信配置" tabindex="-1">短信配置 <a class="header-anchor" href="#短信配置" aria-label="Permalink to &quot;短信配置&quot;">​</a></h1><p>本章节，介绍项目的短信功能。该功能提供统一的短信 API 给其它模块，使它们可以快速接入短信功能，无需关心不同短信平台的具体对接。</p><p>短信采用异步发送，基于 <a href="./message-queue/event">消息队列</a>，如下图所示：</p><p><img src="'+i+'" alt="整体流程"></p><p>该功能由 <code>yudao-module-system</code> 模块实现，其中：</p><ul><li><a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-system/src/main/java/cn/iocoder/yudao/module/system/service/sms/" target="_blank" rel="noreferrer"><code>service/sms</code></a> ：短信【业务】，提供短信渠道、模板的配置，短信日志的查看，短信的发送等功能</li><li><a href="https://github.com/YunaiV/ruoyi-vue-pro/tree/master/yudao-module-system/src/main/java/cn/iocoder/yudao/module/system/framework/sms" target="_blank" rel="noreferrer"><code>frameowrk/sms</code></a> ：短信【组件】，封装阿里云、腾讯云、华为云、七牛云等短信平台的客户端。</li></ul><h2 id="_1-表结构" tabindex="-1">1. 表结构 <a class="header-anchor" href="#_1-表结构" aria-label="Permalink to &quot;1. 表结构&quot;">​</a></h2><p><img src="'+c+'" alt="表结构"></p><h2 id="_2-短信配置" tabindex="-1">2. 短信配置 <a class="header-anchor" href="#_2-短信配置" aria-label="Permalink to &quot;2. 短信配置&quot;">​</a></h2><p>本小节，讲解如何配置短信功能，整个过程如下：</p><ul><li>新建一个短信【渠道】，配置对应短信平台的账号</li><li>新建一个短信【模版】，配置对应短信平台的模板</li><li>测试该短信模板，查看对应的短信【日志】，确认是否发送成功</li></ul><h3 id="_2-1-新建短信渠道" tabindex="-1">2.1 新建短信渠道 <a class="header-anchor" href="#_2-1-新建短信渠道" aria-label="Permalink to &quot;2.1 新建短信渠道&quot;">​</a></h3><p>① 点击 [系统管理 -&gt; 消息中心 -&gt; 短信管理 -&gt; 短信渠道] 菜单，查看短信渠道的列表。如下图所示：</p><p><img src="'+p+'" alt="短信渠道的列表"></p><p>② 点击 [新增] 按钮，选择渠道编码为【调试（钉钉）】，并填写信息如下图：</p><p><img src="'+n+`" alt="短信渠道的新增"></p><div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">短信 API 的账号</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">696b5d8ead48071237e4aa5861ff08dbadb2b4ded1c688a7b7c9afc615579859</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">短信 API 的密钥</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">SEC5c4e5ff888bc8a9923ae47f59e7ccd30af1f14d93c55b4e2c9cb094e35aeed67</span></span></code></pre></div><p>疑问 1：为什么选择渠道编码为【调试（钉钉）】？</p><p>该类型使用钉钉机器人来模拟短信发送，用于日常调试。</p><ul><li>短信 API 的账号，对应机器人的 Webhook 的 <code>access_token</code> 参数</li><li>短信 API 的密钥，对应机器人的安全设置的加签</li></ul><p>上图使用的配置，是艿艿自己的钉钉机器人。正式使用时，必须参考 <a href="https://open.dingtalk.com/document/group/custom-robot-access" target="_blank" rel="noreferrer">《钉钉开放平台 —— 自定义机器人接入 》</a> 文档，申请自己的专属机器人。</p><p>疑问 2：可以选择其它渠道编码吗？</p><p>当然可以，这里主要考虑部分同学暂时没有申请短信平台，所以使用【调试（钉钉）】渠道编码。</p><p>不同短信平台的配置，可见 <a href="#_6-短信平台附录">「6. 短信平台附录」</a> 小节。</p><h3 id="_2-2-新建短信模板" tabindex="-1">2.2 新建短信模板 <a class="header-anchor" href="#_2-2-新建短信模板" aria-label="Permalink to &quot;2.2 新建短信模板&quot;">​</a></h3><p>① 点击 [系统管理 -&gt; 消息中心 -&gt; 短信管理 -&gt; 短信模板] 菜单，查看短信模板的列表。如下图所示：</p><p><img src="`+d+'" alt="短信模板的新增"></p><p>② 点击 [新增] 按钮，选择刚创建的短信渠道，并填写信息如下图：</p><p><img src="'+l+'" alt="短信模板的新增"></p><ul><li>短信渠道编号：发送该短信模板时，使用的短信渠道，即使用哪个短信平台进行发送</li><li>模板编号：短信模板的唯一标识，使用短信 API 时，通过它标识使用的短信模板</li><li>模板内容：短信模板的内容，使用 <code>{var}</code> 作为占位符，例如说 <code>{name}</code>、<code>{code}</code> 等</li><li>短信 API 模板编号：短信平台的短信模板的编号，需要保证该模板在短信平台已经审核通过</li><li>开启状态：短信模板被禁用时，该短信模板将不发送短信，只记录短信日志</li></ul><p>疑问：为什么设计短信模板的功能？</p><p>在一些场景下，需要修改短信模板所使用的短信平台。例如说：短信平台出现故障，或者切换短信平台等等。</p><p>此时，只需要修改短信模板的两个属性：短信渠道编号、短信 API 模板编号，无需重启应用。</p><h3 id="_2-3-查看短信日志" tabindex="-1">2.3 查看短信日志 <a class="header-anchor" href="#_2-3-查看短信日志" aria-label="Permalink to &quot;2.3 查看短信日志&quot;">​</a></h3><p>① 使用钉钉，扫码 <a href="./">图片</a> 加入机器人所在的【ruoyi-vue-pro 短信测试群】，查看测试短信的模拟发送。</p><p>② 点击 [测试] 按钮，输入任一手机号，进行该短信模板的模拟发送。如下图所示：</p><p><img src="'+m+'" alt="测试短信模板"></p><p><img src="'+u+'" alt="测试短信模板"></p><p>友情提示：如果使用的短信渠道是阿里云、腾讯云等正式的短信平台，则会发送到填写的手机号中。例如说：</p><p><img src="'+h+'" alt="接收示例"></p><p>③ 点击 [系统管理 -&gt; 消息中心 -&gt; 短信管理 -&gt; 短信日志] 采单，可以查看到每条短信的发送状态、接收状态。如下图所示：</p><p><img src="'+g+'" alt="短信日志"></p><p>常见问题：为什么日志的接受状态，一直处理“等待结果”？</p><p>因为你没配置短信回调 URL，导致短信平台无法回调我们的系统，所以一直等待结果。具体怎么配置，可见 <a href="#_6-短信平台附录">短信平台附录</a> 小节。</p><h2 id="_3-短信发送" tabindex="-1">3. 短信发送 <a class="header-anchor" href="#_3-短信发送" aria-label="Permalink to &quot;3. 短信发送&quot;">​</a></h2><h3 id="_3-1-smssendapi" tabindex="-1">3.1 SmsSendApi <a class="header-anchor" href="#_3-1-smssendapi" aria-label="Permalink to &quot;3.1 SmsSendApi&quot;">​</a></h3><p>使用 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-system/src/main/java/cn/iocoder/yudao/module/system/api/sms/SmsSendApi.java" target="_blank" rel="noreferrer">SmsSendApi</a> 进行短信的发送，支持多种用户类型。它的方法如下：</p><p><img src="'+a+'" alt="短信发送"></p><h3 id="_3-2-实战案例" tabindex="-1">3.2 实战案例 <a class="header-anchor" href="#_3-2-实战案例" aria-label="Permalink to &quot;3.2 实战案例&quot;">​</a></h3><p>以工作流申请通过时，发送短信为例子，讲解 SmsSendApi 的使用。</p><p>① 引入 <code>yudao-module-system</code> 依赖，如下图所示：</p><p>图片纠错：最新版本引入 <code>yudao-module-system</code> 依赖即可，因为 <code>yudao-module-system-api</code> 已经合并到 <code>yudao-module-system</code> 中。</p><p><img src="'+_+'" alt=" 依赖"></p><p>② 新建对应的短信模板，如下图所示：</p><p><img src="'+E+'" alt="新建短信模板"></p><p>③ 使用 Spring 注入 SmsSendApi Bean，调用对应的短信发送方法。如下图所示：</p><p><img src="'+A+'" alt="调用 SmsSendApi 方法"></p><h2 id="_4-验证码发送" tabindex="-1">4. 验证码发送 <a class="header-anchor" href="#_4-验证码发送" aria-label="Permalink to &quot;4. 验证码发送&quot;">​</a></h2><h3 id="_4-1-smscodeapi" tabindex="-1">4.1 SmsCodeApi <a class="header-anchor" href="#_4-1-smscodeapi" aria-label="Permalink to &quot;4.1 SmsCodeApi&quot;">​</a></h3><p>使用 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-system/src/main/java/cn/iocoder/yudao/module/system/api/sms/SmsCodeApi.java" target="_blank" rel="noreferrer">SmsCodeApi</a> 进行【验证码】短信的发送，例如说：用户手机验证码登录、用户忘记密码等等。它的方法如下：</p><p><img src="'+a+'" alt="短信发送"></p><p>验证码使用 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-system/src/main/java/cn/iocoder/yudao/module/system/dal/dataobject/sms/SmsCodeDO.java" target="_blank" rel="noreferrer"><code>system_sms_code</code></a> 表进行存储，默认每天最多发送 10 条，每分钟发送 1 条，有效期为 10 分钟，可通过 <code>yudao.sms-code</code> 配置项进行自定义：</p><p><img src="'+b+'" alt=" 配置项"></p><h3 id="_4-2-实战案例" tabindex="-1">4.2 实战案例 <a class="header-anchor" href="#_4-2-实战案例" aria-label="Permalink to &quot;4.2 实战案例&quot;">​</a></h3><p>以会员用户手机验证码登录为例子，讲解 SmsCodeApi 的使用。</p><p>① 引入 <code>yudao-module-system</code> 依赖，如下图所示：</p><p>图片纠错：最新版本引入 <code>yudao-module-system</code> 依赖即可，因为 <code>yudao-module-system-api</code> 已经合并到 <code>yudao-module-system</code> 中。</p><p><img src="'+y+'" alt=" 依赖"></p><p>② 新建对应的短信模板，如下图所示：</p><p><img src="'+f+'" alt="新建短信模板"></p><p>③ 在 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-system/src/main/java/cn/iocoder/yudao/module/system/enums/sms/SmsSceneEnum.java" target="_blank" rel="noreferrer">SmsSceneEnum</a> 中，枚举会员用户的手机号登录的场景，如下图所示：</p><p><img src="'+k+'" alt="SmsSceneEnum 枚举"></p><p>④ 使用 Spring 注入 SmsCodeApi Bean，调用对应的短信验证码的发送与使用方法。如下图所示：</p><p><img src="'+D+'" alt="调用 SmsCodeApi 方法"></p><h2 id="_5-短信客户端" tabindex="-1">5. 短信客户端 <a class="header-anchor" href="#_5-短信客户端" aria-label="Permalink to &quot;5. 短信客户端&quot;">​</a></h2><p><a href="https://github.com/YunaiV/ruoyi-vue-pro/tree/master/yudao-module-system/src/main/java/cn/iocoder/yudao/module/system/framework/sms" target="_blank" rel="noreferrer"><code>frameowrk/sms</code></a> 短信【组件】，对接阿里云、腾讯云等短信平台，提供统一的短信客户端，提供给 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-system/src/main/java/cn/iocoder/yudao/module/system/service/sms/" target="_blank" rel="noreferrer"><code>service/sms</code></a> 短信【业务】模块来调用。</p><h3 id="_5-1-smsclient" tabindex="-1">5.1 SmsClient <a class="header-anchor" href="#_5-1-smsclient" aria-label="Permalink to &quot;5.1 SmsClient&quot;">​</a></h3><p><a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-system/src/main/java/cn/iocoder/yudao/module/system/framework/sms/core/client/SmsClient.java" target="_blank" rel="noreferrer">SmsClient</a> 接口，定义短信客户端的方法。代码如下：</p><p><img src="'+S+'" alt="SmsClient 接口"></p><p>每个短信平台，都对应一个 SmsClient 实现类。</p><p><img src="'+B+'" alt="SmsClient 实现"></p><h3 id="_5-2-对接其它短信平台" tabindex="-1">5.2 对接其它短信平台 <a class="header-anchor" href="#_5-2-对接其它短信平台" aria-label="Permalink to &quot;5.2 对接其它短信平台&quot;">​</a></h3><p>如果你想要对接其它短信平台，自定义一个 SmsClient 实现类，并使用 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-system/src/main/java/cn/iocoder/yudao/module/system/framework/sms/core/client/impl/SmsClientFactoryImpl.java#L73-L85" target="_blank" rel="noreferrer">SmsClientFactoryImpl</a> 进行创建。代码如下：</p><p><img src="'+F+'" alt="SmsClientFactoryImpl 创建客户端"></p><h2 id="_6-短信平台附录" tabindex="-1">6. 短信平台附录 <a class="header-anchor" href="#_6-短信平台附录" aria-label="Permalink to &quot;6. 短信平台附录&quot;">​</a></h2><p>一般情况下，建议接入 2-3 个短信平台，避免某个短信平台故障时，影响业务的正常运行。</p><p>例如说，手机验证码的短信平台 A 故障时，赶紧将短信验证码切换到短信平台 B 上，否则用户将无法正常登录或是注册。</p><h3 id="_6-1-阿里云" tabindex="-1">6.1 阿里云 <a class="header-anchor" href="#_6-1-阿里云" aria-label="Permalink to &quot;6.1 阿里云&quot;">​</a></h3><p>① 短信 API 的账号、密钥，可通过 <a href="https://ram.console.aliyun.com/manage/ak" target="_blank" rel="noreferrer">阿里云 —— AccessKey</a> 获取。</p><p>② 短信发送回调 URL，可通过 <a href="https://dysms.console.aliyun.com/general/upward" target="_blank" rel="noreferrer">阿里云 —— 短信服务 —— 通用设置</a> 配置。它对应的是 SmsCallbackController 的 <code>#receiveAliyunSmsStatus(...)</code> 地址。</p><h3 id="_6-2-腾讯云" tabindex="-1">6.2 腾讯云 <a class="header-anchor" href="#_6-2-腾讯云" aria-label="Permalink to &quot;6.2 腾讯云&quot;">​</a></h3><p>① 短信 API 的账号、密钥，可通过 <a href="https://console.cloud.tencent.com/cam/capi" target="_blank" rel="noreferrer">腾讯云 —— API 密钥管理</a> 获取。</p><p>注意！！！</p><p>腾讯云需要额外使用 <a href="https://console.cloud.tencent.com/smsv2/app-manage" target="_blank" rel="noreferrer">SDKAppID</a> 参数，它的账号需要采用 <code>secretId SDKAppID</code> 格式。</p><p>例如说：在“API 密钥管理”获得了 <code>SecretId</code> 为 <code>A</code>，<code>SecretKey</code> 为 <code>B</code>，在“SDKAppID”获得了 <code>SDKAppID</code> 为 <code>18</code>，则配置短信 API 的账号为 <code>A 18</code>，短信 API 的密钥为 <code>B</code>。</p><p>② 短信发送回调 URL，可通过 <a href="https://console.cloud.tencent.com/smsv2/app-setting" target="_blank" rel="noreferrer">腾讯云 —— 短信 —— 基础配置</a> 配置。它对应的是 SmsCallbackController 的 <code>#receiveTencentSmsStatus(...)</code> 地址。</p><h3 id="_6-3-华为云" tabindex="-1">6.3 华为云 <a class="header-anchor" href="#_6-3-华为云" aria-label="Permalink to &quot;6.3 华为云&quot;">​</a></h3><p>① 短信 API 的账号、密钥，可通过 <a href="https://console.huaweicloud.com/iam/#/mine/accessKey" target="_blank" rel="noreferrer">华为云 —— 访问密钥</a> 获取。</p><p>注意！！！</p><p>华为云需要额外使用 sender 通道号，它的账号需要采用 <code>AccessKeyId sender</code> 格式。</p><p>例如说：在“华为云访问密钥”获得了 <code>AccessKeyId</code> 为 <code>A</code>，<code>SecretAccessKey</code> 为 <code>B</code>，在“华为云签名”获得了 <code>sender</code> 为 <code>8824060312575</code>，则配置短信 API 的账号为 <code>A 8824060312575</code>，短信 API 的密钥为 <code>B</code>。</p><p>② 短信发送回调 URL，可以通过我们项目的 [系统管理 -&gt; 消息中心 -&gt; 短信管理 -&gt; 短信渠道] 菜单，配置它的“短信发送回调 URL”字段即可。它对应的是 SmsCallbackController 的 <code>#receiveHuaweiSmsStatus(...)</code> 地址。</p><p>补充说明：如果发送短信时，提示“405 鉴权失败”的话，怎么办？</p><p>可参考 <a href="https://gitee.com/zhijiantianya/yudao-cloud/issues/IASUWI" target="_blank" rel="noreferrer">https://gitee.com/zhijiantianya/yudao-cloud/issues/IASUWI</a> 说明，我目前暂时没碰到过，不确定是不是这么解决是合理的~</p><h3 id="_6-4-七牛云" tabindex="-1">6.4 七牛云 <a class="header-anchor" href="#_6-4-七牛云" aria-label="Permalink to &quot;6.4 七牛云&quot;">​</a></h3><p>① 短信 API 的账号、密钥，可通过 <a href="https://portal.qiniu.com/developer/user/key" target="_blank" rel="noreferrer">七牛云 —— 密钥管理</a> 获取。</p><p>② 短信发送回调 URL，可通过 <a href="https://portal.qiniu.com/sms/settings" target="_blank" rel="noreferrer">七牛云 —— 云短信 —— 设置</a> 配置。它对应的是 SmsCallbackController 的 <code>#receiveQiniuSmsStatus(...)</code> 地址。</p><h3 id="_6-5-更多短信平台" tabindex="-1">6.5 更多短信平台 <a class="header-anchor" href="#_6-5-更多短信平台" aria-label="Permalink to &quot;6.5 更多短信平台&quot;">​</a></h3><p>短信平台非常的多，欢迎给我们 pull request 贡献。</p><p>例如说：合一、云片、京东云、容联云、亿美软通、天翼云、网易云等等。</p><p>如果你想参与，可以添加 <code>wangwenbin-server</code> 微信好，备注“短信”即可。</p>',111)])])}const Y=o(v,[["render",x]]);export{V as __pageData,Y as default};
